    {
        var connectionString = s_appFactory!.GetConnectionString("openai")
            ?? throw new InvalidOperationException("Could not get connection string for 'openai'.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(connectionString),
            new Azure.AzureKeyCredential("eval-key"))
