using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;
    private static DistributedApplicationFactory? s_appFactory;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        s_appFactory = new DistributedApplicationFactory(typeof(Projects.MyApp_AppHost));
        await s_appFactory.StartAsync();

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-reports"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(GetChatClient()));
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (s_appFactory is not null)
        {
            await s_appFactory.DisposeAsync();
        }
    }

    private static IChatClient GetChatClient()
    {
        var connectionString = s_appFactory!.GetConnectionString("openai").GetAwaiter().GetResult()
            ?? throw new InvalidOperationException("Could not get connection string for 'openai'.");

        var azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(connectionString),
            new Azure.AzureKeyCredential("eval-key"));

        return new OpenAIChatClient(azureClient.GetChatClient("chat"));
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var chatClient = GetChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertNoFailures(result);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndFluent()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsGroundedAndFluent));

        var chatClient = GetChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var result = await scenario.EvaluateAsync(messages, response);

        AssertNoFailures(result);
    }

    private static void AssertNoFailures(EvaluationResult result)
    {
        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(
                metric.Value.Interpretation?.Rating == EvaluationRating.Inconclusive &&
                metric.Value.ContainsDiagnostics(d => d.Severity == EvaluationDiagnosticSeverity.Error),
                $"Metric '{metric.Key}' contains errors.");
        }
    }
}

