             new(ChatRole.User, "What is the capital of France?")
         };

         var response = await chatClient.GetResponseAsync(messages);

         var result = await scenario.EvaluateAsync(messages, response);

         AssertNoFailures(result);
     }

     private static void AssertNoFailures(EvaluationResult result)
     {
         foreach (var metric in result.Metrics)
         {
             Assert.IsFalse(
                 metric.Value.Interpretation?.Rating == EvaluationRating.Inconclusive &&
                 metric.Value.ContainsDiagnostics(d => d.Severity == EvaluationDiagnosticSeverity.Error),
                 $"Metric '{metric.Key}' contains errors.");
         }
     }
 }
